import json

def extract_ve(path):
    value_by_step = {}
    eval_by_step = {}
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            step = d.get('step')
            if 'value_mean' in d:
                value_by_step[step] = d['value_mean']
            if 'eval_return' in d:
                eval_by_step[step] = d['eval_return']

    results = []
    for step in sorted(eval_by_step.keys()):
        eval_ret = eval_by_step[step]
        value = value_by_step.get(step)
        ve_ratio = None
        if value is not None and eval_ret > 0:
            ve_ratio = round(value / eval_ret, 4)
        results.append({
            'step': step,
            'eval_return': round(eval_ret, 4),
            'value_mean': round(value, 4) if value is not None else None,
            've_ratio': ve_ratio
        })
    return results

a = extract_ve('logdir/exp_019a_v2_pickcube_baseline/metrics.jsonl')
b = extract_ve('logdir/exp_019b_pickcube_civo_trigger/metrics.jsonl')

result = {
    'description': 'PickCube V/E trajectory for CIVO cross-environment validation',
    'experiments': {
        'exp_019a_v2_pickcube_baseline': {
            'config': 'vanilla DreamerV3 (no dt_emb, no gate)',
            'checkpoints': a
        },
        'exp_019b_pickcube_civo_trigger': {
            'config': 'trained dt_emb + gate (CIVO trigger, gate_fixed_dt=2, imag_horizon=8)',
            'checkpoints': b
        }
    }
}

print(json.dumps(result, indent=2))
